  2603  void Mle::HandleUdpReceive(Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  2604  {
  2605      Header          header;
  2606      uint32_t        keySequence;
  2607      const uint8_t * mleKey;
  2608      uint32_t        frameCounter;
  2609      uint8_t         messageTag[4];
  2610      uint8_t         nonce[13];
  2611      Mac::ExtAddress macAddr;
  2612      Crypto::AesCcm  aesCcm;
  2613      uint16_t        mleOffset;
  2614      uint8_t         buf[64];
  2615      uint16_t        length;
  2616      uint8_t         tag[4];
  2617      uint8_t         tagLength;
  2618      uint8_t         command;
  2619      Neighbor *      neighbor;
  2620
  2621      VerifyOrExit(aMessageInfo.GetLinkInfo() != NULL);
  2622      VerifyOrExit(aMessageInfo.GetHopLimit() == kMleHopLimit);
  2623
  2624      length = aMessage.Read(aMessage.GetOffset(), sizeof(header), &header);
  2625      VerifyOrExit(header.IsValid() && header.GetLength() <= length);
  2626
  2627      if (header.GetSecuritySuite() == Header::kNoSecurity)
  2628      {
  2629          aMessage.MoveOffset(header.GetLength());
  2630
  2631          switch (header.GetCommand())
  2632          {
  2633          case Header::kCommandDiscoveryRequest:
  2634              Get<MleRouter>().HandleDiscoveryRequest(aMessage, aMessageInfo);
  2635              break;
  2636
  2637          case Header::kCommandDiscoveryResponse:
  2638              HandleDiscoveryResponse(aMessage, aMessageInfo);
  2639              break;
  2640
  2641          default:
  2642              break;
  2643          }
  2644
  2645          ExitNow();
  2646      }
  2647
  2648      VerifyOrExit(mRole != OT_DEVICE_ROLE_DISABLED && header.GetSecuritySuite() == Header::k154Security);
  2649
  2650      keySequence = header.GetKeyId();
  2651
  2652      if (keySequence == Get<KeyManager>().GetCurrentKeySequence())
  2653      {
  2654          mleKey = Get<KeyManager>().GetCurrentMleKey();
  2655      }
  2656      else
  2657      {
  2658          mleKey = Get<KeyManager>().GetTemporaryMleKey(keySequence);
  2659      }
  2660
  2661      VerifyOrExit(aMessage.GetOffset() + header.GetLength() + sizeof(messageTag) <= aMessage.GetLength());
  2662      aMessage.MoveOffset(header.GetLength() - 1);
  2663
  2664      aMessage.Read(aMessage.GetLength() - sizeof(messageTag), sizeof(messageTag), messageTag);
  2665      SuccessOrExit(aMessage.SetLength(aMessage.GetLength() - sizeof(messageTag)));
  2666
  2667      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  2668      frameCounter = header.GetFrameCounter();
  2669      GenerateNonce(macAddr, frameCounter, Mac::Frame::kSecEncMic32, nonce);
  2670
  2671      aesCcm.SetKey(mleKey, 16);
  2672      SuccessOrExit(
  2673          aesCcm.Init(sizeof(aMessageInfo.GetPeerAddr()) + sizeof(aMessageInfo.GetSockAddr()) + header.GetHeaderLength(),
  2674                      aMessage.GetLength() - aMessage.GetOffset(), sizeof(messageTag), nonce, sizeof(nonce)));
  2675
  2676      aesCcm.Header(&aMessageInfo.GetPeerAddr(), sizeof(aMessageInfo.GetPeerAddr()));
  2677      aesCcm.Header(&aMessageInfo.GetSockAddr(), sizeof(aMessageInfo.GetSockAddr()));
  2678      aesCcm.Header(header.GetBytes() + 1, header.GetHeaderLength());
  2679
  2680      mleOffset = aMessage.GetOffset();
  2681
  2682      while (aMessage.GetOffset() < aMessage.GetLength())
  2683      {
  2684          length = aMessage.Read(aMessage.GetOffset(), sizeof(buf), buf);
  2685          aesCcm.Payload(buf, buf, length, false);
  2686  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2687          aMessage.Write(aMessage.GetOffset(), length, buf);
  2688  #endif
  2689          aMessage.MoveOffset(length);
  2690      }
  2691
  2692      tagLength = sizeof(tag);
  2693      aesCcm.Finalize(tag, &tagLength);
  2694  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2695      VerifyOrExit(memcmp(messageTag, tag, sizeof(tag)) == 0);
  2696  #endif
  2697
  2698      if (keySequence > Get<KeyManager>().GetCurrentKeySequence())
  2699      {
  2700          Get<KeyManager>().SetCurrentKeySequence(keySequence);
  2701      }
  2702
  2703      aMessage.SetOffset(mleOffset);
  2704
  2705      aMessage.Read(aMessage.GetOffset(), sizeof(command), &command);
  2706      aMessage.MoveOffset(sizeof(command));
  2707
  2708      switch (mRole)
  2709      {
  2710      case OT_DEVICE_ROLE_DETACHED:
  2711      case OT_DEVICE_ROLE_CHILD:
  2712          neighbor = GetNeighbor(macAddr);
  2713          break;
  2714
  2715      case OT_DEVICE_ROLE_ROUTER:
  2716      case OT_DEVICE_ROLE_LEADER:
  2717          if (command == Header::kCommandChildIdResponse)
  2718          {
  2719              neighbor = GetNeighbor(macAddr);
  2720          }
  2721          else
  2722          {
  2723              neighbor = Get<MleRouter>().GetNeighbor(macAddr);
  2724          }
  2725
  2726          break;
  2727
  2728      default:
  2729          neighbor = NULL;
  2730          break;
  2731      }
  2732
  2733      if (neighbor != NULL && neighbor->GetState() == Neighbor::kStateValid)
  2734      {
  2735          if (keySequence == neighbor->GetKeySequence())
  2736          {
  2737              if (frameCounter < neighbor->GetMleFrameCounter())
  2738              {
  2739                  otLogDebgMle("mle frame reject 1");
  2740                  ExitNow();
  2741              }
  2742          }
  2743          else
  2744          {
  2745              if (keySequence <= neighbor->GetKeySequence())
  2746              {
  2747                  otLogDebgMle("mle frame reject 2");
  2748                  ExitNow();
  2749              }
  2750
  2751              neighbor->SetKeySequence(keySequence);
  2752              neighbor->SetLinkFrameCounter(0);
  2753          }
  2754
  2755          neighbor->SetMleFrameCounter(frameCounter + 1);
  2756      }
  2757      else
  2758      {
  2759          if (!(command == Header::kCommandLinkRequest || command == Header::kCommandLinkAccept ||
  2760                command == Header::kCommandLinkAcceptAndRequest || command == Header::kCommandAdvertisement ||
  2761                command == Header::kCommandParentRequest || command == Header::kCommandParentResponse ||
  2762                command == Header::kCommandChildIdRequest || command == Header::kCommandChildUpdateRequest ||
  2763                command == Header::kCommandChildUpdateResponse || command == Header::kCommandAnnounce))
  2764          {
  2765              otLogDebgMle("mle sequence unknown! %d", command);
  2766              ExitNow();
  2767          }
  2768      }
